_install('ngt_nd', '"""Bounded nonlinear Gaussian tied tree in d dimensions, and its grid oracle (torch).\n\nModel: z_root ~ stationary law; children z_{wi} = phi_i(z_w) + psi * eps (eps ~ N(0, I_d)), same phi at\nevery height; phi_i(z) = b_i + W_i sig(z) + U_i tanh(3 sig(z)), sig(z) = z / (1 + |z|) coordinatewise.\nOracle: belief propagation with the TRUE kernel on a regular grid over [-lim, lim]^d.  The Gaussian\ntransition is applied as a separable blur (child-side) plus multilinear interpolation at phi_i(grid)\n(upward), and as a multilinear splat plus blur (for the stationary law).\n"""\nimport math\nimport numpy as np\nimport torch\nimport torch.nn.functional as Fn\n\nS = 3\nDEV = "cuda" if torch.cuda.is_available() else "cpu"\n\n\ndef sig(z):\n    return z / (1.0 + np.abs(z))\n\n\nclass NDKernel:\n    def __init__(self, b, W, U, psi):\n        self.b, self.W, self.U, self.psi = np.asarray(b), np.asarray(W), np.asarray(U), float(psi)\n        self.d = self.b.shape[1]\n\n    def phi(self, z):\n        """z (..., d) -> (..., S, d)"""\n        p = sig(z); t = np.tanh(3 * p)\n        return np.stack([self.b[i] + p @ self.W[i].T + t @ self.U[i].T for i in range(S)], -2)\n\n\ndef random_kernel(d, rng, psi=0.35, sv_range=(1.3, 2.0)):\n    b, W, U = [], [], []\n    for _ in range(S):\n        Q, _ = np.linalg.qr(rng.normal(size=(d, d)))\n        sv = rng.uniform(*sv_range, d)\n        Wi = Q @ np.diag(sv)\n        Ui = rng.normal(size=(d, d)); Ui *= 0.3 * sv.min() / np.linalg.norm(Ui, 2)\n        b.append(rng.uniform(-0.3, 0.3, d)); W.append(Wi); U.append(Ui)\n    return NDKernel(np.array(b), np.array(W), np.array(U), psi)\n\n\ndef sample_trees(ker, U, L, rng, burn=40):\n    d = ker.d\n    z = np.zeros((U, d))\n    for _ in range(burn):\n        i = rng.integers(S, size=U)\n        z = ker.phi(z)[np.arange(U), i] + ker.psi * rng.normal(size=(U, d))\n    root = z.copy()\n    z = z[:, None, :]\n    for _ in range(L):\n        m = ker.phi(z)                                             # (U, nodes, S, d)\n        z = (m + ker.psi * rng.normal(size=m.shape)).reshape(U, -1, d)\n    return z, root\n\n\nclass GridOracle:\n    def __init__(self, ker, n=81, lim=4.0):\n        self.ker, self.n, self.lim, self.d = ker, n, lim, ker.d\n        axis = np.linspace(-lim, lim, n)\n        mesh = np.stack(np.meshgrid(*([axis] * self.d), indexing="ij"), -1).reshape(-1, self.d)\n        self.P = torch.tensor(mesh, dtype=torch.float32, device=DEV)            # (n^d, d)\n        ph = ker.phi(mesh)                                                      # (n^d, S, d)\n        self.phiP = [torch.tensor(ph[:, i], dtype=torch.float32, device=DEV) for i in range(S)]\n        h = 2 * lim / (n - 1)\n        r = int(math.ceil(4 * ker.psi / h))\n        k = torch.exp(-0.5 * (torch.arange(-r, r + 1, device=DEV, dtype=torch.float32) * h / ker.psi) ** 2)\n        self.k1 = (k / k.sum()).view(1, 1, -1)\n        self.pi = self._stationary()\n\n    # --- grid operators -------------------------------------------------------------\n    def _blur(self, f):\n        """f (N, n^d) -> Gaussian-blurred along every axis (zero padding: mass leaving the box is lost)."""\n        N, n, d = f.shape[0], self.n, self.d\n        g = f.view(N, *([n] * d))\n        for ax in range(d):\n            g = g.movedim(ax + 1, -1)\n            sh = g.shape\n            g = Fn.conv1d(g.reshape(-1, 1, n), self.k1, padding=self.k1.shape[-1] // 2).reshape(sh)\n            g = g.movedim(-1, ax + 1)\n        return g.reshape(N, -1)\n\n    def _interp(self, f, pts):\n        """f (N, n^d) grid values, pts (M, d) -> values at pts (N, M), multilinear, 0 outside."""\n        N, n, d = f.shape[0], self.n, self.d\n        inp = f.view(N, 1, *([n] * d))\n        g = (pts / self.lim).flip(-1)                         # grid_sample wants (x=last axis, ...)\n        g = g.view(1, *([1] * (d - 1)), -1, d).expand(N, *([1] * (d - 1)), -1, d)\n        out = Fn.grid_sample(inp, g, mode="bilinear", padding_mode="zeros", align_corners=True)\n        return out.reshape(N, -1)\n\n    def _splat(self, w, pts):\n        """Adjoint of _interp: put mass w (N, M) at locations pts (M, d) onto the grid (N, n^d)."""\n        n, d = self.n, self.d\n        u = (pts + self.lim) / (2 * self.lim) * (n - 1)\n        lo = torch.floor(u).long(); fr = u - lo\n        out = torch.zeros((w.shape[0], n ** d), device=DEV)\n        for corner in range(2 ** d):\n            off = torch.tensor([(corner >> k) & 1 for k in range(d)], device=DEV)\n            idx = lo + off\n            wt = torch.prod(torch.where(off.bool(), fr, 1 - fr), -1)\n            ok = ((idx >= 0) & (idx < n)).all(-1)\n            flat = torch.zeros_like(idx[:, 0])\n            for k in range(d):\n                flat = flat * n + idx[:, k].clamp(0, n - 1)\n            out.index_add_(1, flat[ok], w[:, ok] * wt[ok])\n        return out\n\n    def _stationary(self, iters=300):\n        pi = torch.full((1, self.n ** self.d), 1.0 / self.n ** self.d, device=DEV)\n        for _ in range(iters):\n            pi = sum(self._blur(self._splat(pi, self.phiP[i])) for i in range(S)) / S\n            pi = pi / pi.sum()\n        return pi[0] + 1e-30\n\n    # --- inference --------------------------------------------------------------------\n    def root_mean(self, X, chunk=10):\n        """X (T, n_leaves, d) numpy -> posterior mean of the root (T, d)."""\n        out = []\n        for a in range(0, X.shape[0], chunk):\n            Xc = torch.tensor(X[a:a + chunk], dtype=torch.float32, device=DEV)\n            T, nl, d = Xc.shape\n            L = int(round(math.log(nl) / math.log(S)))\n            x = Xc.reshape(-1, S, d)                                               # height-1 children\n            lb = torch.zeros((x.shape[0], self.P.shape[0]), device=DEV)\n            for i in range(S):\n                lb += -((x[:, i, None, :] - self.phiP[i][None]) ** 2).sum(-1) / (2 * self.ker.psi ** 2)\n            b = torch.exp(lb - lb.max(1, keepdim=True).values)\n            u = b / b.sum(1, keepdim=True)\n            for h in range(2, L + 1):\n                uc = self._blur(u).view(-1, S, u.shape[1])\n                b = torch.ones((uc.shape[0], u.shape[1]), device=DEV)\n                for i in range(S):\n                    m = self._interp(uc[:, i], self.phiP[i]).clamp_min(0)\n                    b = b * (m / (m.max(1, keepdim=True).values + 1e-30))\n                u = (b + 1e-30) / (b + 1e-30).sum(1, keepdim=True)\n            post = u * self.pi\n            post = post / post.sum(1, keepdim=True)\n            out.append((post @ self.P).cpu().numpy())\n        return np.concatenate(out)\n')
_install('codebook_torch', '"""GPU version of codebook.py (tied codebook tree, exact EM).  Same model, same updates, same\nstatistics; torch instead of numpy so the E-step\'s batched matrix products run on a GPU.\nProbabilities in float32 with per-message rescaling; log-likelihood and M-step sums in float64.\n"""\nimport copy\nimport math\nimport numpy as np\nimport torch\n\nS = 3\nFLOOR = 1e-30\nDEV = "cuda" if torch.cuda.is_available() else "cpu"\nF32, F64 = torch.float32, torch.float64\n\n\nclass Codebook:\n    def __init__(self, M, c, tau):\n        self.M = torch.as_tensor(M, dtype=F32, device=DEV)      # (S, v, v): M[i, a\', a]\n        self.c = torch.as_tensor(c, dtype=F32, device=DEV)      # (v, d)\n        self.tau = float(tau)\n\n    @property\n    def v(self):\n        return self.c.shape[0]\n\n    def stationary(self, iters=500):\n        Mb = self.M.mean(0).to(F64)\n        mu = torch.full((self.v,), 1.0 / self.v, dtype=F64, device=DEV)\n        for _ in range(iters):\n            mu = Mb @ mu\n        mu = mu + 1e-15\n        return (mu / mu.sum()).to(F32)\n\n    def numpy(self):\n        return self.M.cpu().numpy(), self.c.cpu().numpy(), self.tau\n\n\ndef _leaves(X):\n    if not torch.is_tensor(X):\n        X = np.asarray(X, float)\n    X = torch.as_tensor(X, dtype=F32, device=DEV)\n    return X[..., None] if X.dim() == 2 else X\n\n\ndef _emission(cb, X):\n    d = X.shape[1]\n    lq = -((X[:, None, :] - cb.c[None]) ** 2).sum(-1) / (2 * cb.tau ** 2)\n    mx = lq.max(1, keepdim=True).values\n    u = torch.exp(lq - mx)\n    z = u.sum(1, keepdim=True)\n    ll = (mx.to(F64) + torch.log(z.to(F64))).sum() - X.shape[0] * d * math.log(math.sqrt(2 * math.pi) * cb.tau)\n    return u / z, ll\n\n\ndef upward(cb, X):\n    X = _leaves(X)\n    U, nl, d = X.shape\n    L = int(round(math.log(nl) / math.log(S)))\n    Xf = X.reshape(-1, d)\n    u, ll = _emission(cb, Xf)\n    ups, msgs = {0: u}, {}\n    for h in range(1, L + 1):\n        uc = ups[h - 1].reshape(-1, S, cb.v)\n        m = torch.stack([uc[:, i] @ cb.M[i] for i in range(S)], 1)\n        mx = m.max(2, keepdim=True).values\n        m = m / mx; ll = ll + torch.log(mx.to(F64)).sum()\n        b = m.prod(1) + FLOOR\n        z = b.sum(1, keepdim=True); ll = ll + torch.log(z.to(F64)).sum()\n        msgs[h], ups[h] = m, b / z\n    return ups, msgs, ll, L, Xf\n\n\ndef estep(cb, X):\n    pi = cb.stationary()\n    ups, msgs, ll, L, Xf = upward(cb, X)\n    ll = ll + torch.log((ups[L] @ pi).to(F64)).sum()\n    v = cb.v\n    pair = torch.zeros((S, v, v), dtype=F64, device=DEV)\n    o = pi.expand(ups[L].shape[0], v)\n    for h in range(L, 0, -1):\n        m = msgs[h]\n        uc = ups[h - 1].reshape(-1, S, v)\n        o_child = torch.empty((m.shape[0], S, v), dtype=F32, device=DEV)\n        for i in range(S):\n            others = torch.ones_like(o)\n            for j in range(S):\n                if j != i:\n                    others = others * m[:, j]\n            r = o * others + FLOOR\n            r = r / r.sum(1, keepdim=True)\n            raw = uc[:, i] @ cb.M[i]                                   # unscaled message\n            Z = (r * raw).sum(1, keepdim=True)\n            pair[i] += (cb.M[i].T * ((r / Z).T @ uc[:, i])).to(F64)\n            oc = r @ cb.M[i].T\n            o_child[:, i] = oc / oc.sum(1, keepdim=True)\n        o = o_child.reshape(-1, v)\n    P = o * ups[0]\n    P = P / P.sum(1, keepdim=True)\n    return pair, P, Xf, float(ll)\n\n\ndef mstep(pair, P, Xf, smooth=1e-6):\n    pr = pair + smooth\n    M = (pr / pr.sum(2, keepdim=True)).transpose(1, 2)\n    P64, X64 = P.to(F64), Xf.to(F64)\n    w = P64.sum(0) + 1e-12\n    c = (P64.T @ X64) / w[:, None]\n    sse = (P64 * ((X64[:, None, :] - c[None]) ** 2).sum(-1)).sum()\n    tau = math.sqrt(max(float(sse) / (Xf.shape[0] * Xf.shape[1]), 1e-6))\n    return Codebook(M.to(F32), c.to(F32), tau)\n\n\ndef random_init(X, v, rng):\n    Xf = np.asarray(X, float).reshape(-1, 1) if np.asarray(X).ndim == 2 else np.asarray(X, float).reshape(-1, np.asarray(X).shape[-1])\n    qs = np.quantile(Xf, (np.arange(v) + 0.5) / v, axis=0)\n    c = qs + 0.05 * Xf.std(0) * rng.normal(size=qs.shape)\n    M = rng.dirichlet(np.ones(v), size=(S, v)).transpose(0, 2, 1)\n    return Codebook(M, c, 0.5 * Xf.std() / v ** (1 / Xf.shape[1]) + 0.1)\n\n\ndef run_em(cb, X, iters, tol):\n    prev = -math.inf\n    for _ in range(iters):\n        pair, P, Xf, ll = estep(cb, X)\n        cb = mstep(pair, P, Xf)\n        if ll - prev < tol * abs(ll):\n            break\n        prev = ll\n    return cb, estep(cb, X)[3]\n\n\ndef fit(X, v, rng, restarts=4, iters=250, tol=1e-7):\n    best = None\n    for _ in range(restarts):\n        cb, ll = run_em(random_init(X, v, rng), X, iters, tol)\n        if best is None or ll > best[0]:\n            best = (ll, cb)\n    return best[1], best[0]\n\n\ndef split(cb, rng, jitter=0.05):\n    """v -> 2v symbols: each symbol becomes two copies with slightly separated values; a parent\'s\n    probability of a child symbol is shared between its two copies (small random asymmetry).\n    Both parent copies inherit the parent\'s children law.  The split model has the same likelihood\n    up to the jitter, so EM continues from a model as good as the coarse one."""\n    M, c, tau = cb.numpy()\n    v = c.shape[0]\n    sd = max(tau, 1e-3) * jitter\n    c2 = np.concatenate([c - sd, c + sd])\n    w = 0.5 + 0.05 * rng.uniform(-1, 1, size=(3, v, v))\n    M2 = np.zeros((3, 2 * v, 2 * v))\n    for i in range(3):\n        child = np.concatenate([M[i] * w[i], M[i] * (1 - w[i])], 0)      # (2v children, v parents)\n        M2[i] = np.concatenate([child, child], 1)                          # both parent copies\n    return Codebook(M2, c2, tau)\n\n\ndef fit_coarse_to_fine(X, v_final, rng, v0=4, restarts=4, iters=250, tol=1e-7):\n    """Maximum likelihood by EM, initialised coarse-to-fine: best of `restarts` at v0, then split and\n    refit until v_final.  Returns the fitted models at every size (dict v -> (codebook, ll))."""\n    cb, ll = fit(X, v0, rng, restarts, iters, tol)\n    out = {v0: (cb, ll)}\n    v = v0\n    while v < v_final:\n        cb, ll = run_em(split(cb, rng), X, iters, tol)\n        v *= 2\n        out[v] = (cb, ll)\n    return out\n\n\n# ------------------------------------------------------------------ hard-quantized leaves (Q4)\n# Leaf symbol = its quantile cell (no emission noise); symbol value = cell mean.  All noise lives in\n# the tied M_i at every level, so leaves and latent children are generated the same way.\n\nclass QCodebook(Codebook):\n    def __init__(self, M, c, edges):\n        super().__init__(M, c, 1.0)\n        self.edges = torch.as_tensor(edges, dtype=F32, device=DEV)   # (v-1,) cell boundaries (d = 1)\n\n\ndef quantize(Xf, v):\n    x = np.asarray(Xf, float).ravel()\n    edges = np.quantile(x, np.arange(1, v) / v)\n    idx = np.searchsorted(edges, x)\n    c = np.array([x[idx == a].mean() for a in range(v)])[:, None]\n    return edges, c\n\n\ndef _q_emission(cb, Xf):\n    if getattr(cb, "quant", None) is not None:                      # d > 1: tree-structured VQ\n        idx = cb.quant.assign(Xf, cb.depth)\n    else:\n        idx = torch.searchsorted(cb.edges, Xf[:, 0].contiguous())\n    u = torch.zeros((Xf.shape[0], cb.v), dtype=F32, device=DEV)\n    u[torch.arange(Xf.shape[0], device=DEV), idx] = 1.0\n    return u, torch.zeros((), dtype=F64, device=DEV)     # uniform-in-cell density: constant in M\n\n\ndef _with_q(fn):\n    def wrapped(cb, X, *a, **k):\n        global _emission\n        orig = _emission\n        if isinstance(cb, QCodebook):\n            _emission = _q_emission\n        try:\n            return fn(cb, X, *a, **k)\n        finally:\n            _emission = orig\n    return wrapped\n\n\nq_estep = _with_q(estep)\nq_root_value = _with_q(lambda cb, X, chunk=200: root_value(cb, X, chunk))\n\n\ndef q_run_em(cb, X, iters, tol, smooth=1e-6):\n    prev = -math.inf\n    for _ in range(iters):\n        pair, P, Xf, ll = q_estep(cb, X)\n        pr = pair + smooth\n        new = copy.copy(cb)                                          # keeps quantizer / edges\n        new.M = (pr / pr.sum(2, keepdim=True)).transpose(1, 2).to(F32)\n        cb = new\n        if ll - prev < tol * abs(ll):\n            break\n        prev = ll\n    return cb, q_estep(cb, X)[3]\n\n\ndef q_split(cb, X, rng):\n    """v -> 2v with nested quantile cells (median split of every cell); M shared as in split()."""\n    v = cb.v\n    Xf = np.asarray(X, float).ravel()\n    edges2, c2 = quantize(Xf, 2 * v)\n    M = cb.M.cpu().numpy()\n    w = 0.5 + 0.05 * rng.uniform(-1, 1, size=(3, v, v))\n    M2 = np.zeros((3, 2 * v, 2 * v))\n    order = np.repeat(np.arange(v), 2)            # new cell 2a, 2a+1 refine old cell a\n    for i in range(3):\n        child = np.zeros((2 * v, v))\n        for a2 in range(2 * v):\n            child[a2] = M[i][order[a2]] * (w[i][order[a2]] if a2 % 2 == 0 else 1 - w[i][order[a2]])\n        M2[i] = child[:, order]\n    return QCodebook(M2, c2, edges2)\n\n\ndef q_fit_coarse_to_fine(X, v_final, rng, v0=4, restarts=4, iters=300, tol=1e-8):\n    Xf = np.asarray(X, float).ravel()\n    edges, c = quantize(Xf, v0)\n    best = None\n    for _ in range(restarts):\n        M = rng.dirichlet(np.ones(v0), size=(3, v0)).transpose(0, 2, 1)\n        cb, ll = q_run_em(QCodebook(M, c, edges), X, iters, tol)\n        if best is None or ll > best[1]:\n            best = (cb, ll)\n    cb, ll = best\n    out = {v0: (cb, ll)}\n    v = v0\n    while v < v_final:\n        cb, ll = q_run_em(q_split(cb, X, rng), X, iters, tol)\n        v *= 2\n        out[v] = (cb, ll)\n    return out\n\n\ndef root_value(cb, X, chunk=200):\n    X = _leaves(X)\n    pi = cb.stationary(); out = []\n    for a in range(0, X.shape[0], chunk):\n        ups, _, _, L, _ = upward(cb, X[a:a + chunk])\n        p = ups[L] * pi\n        out.append((p / p.sum(1, keepdim=True)) @ cb.c)\n    r = torch.cat(out).cpu().numpy()\n    return r[:, 0] if r.shape[1] == 1 else r\n')
_install('codebook_vq', '"""Hard-quantized codebook tree for d > 1 (srhm.tex section 8.8, V2).\n\nLeaves are quantized by tree-structured vector quantization (TSVQ): cell a at depth k splits into cells\n2a, 2a+1 at depth k+1 by 2-means (started along the cell\'s principal axis).  Cells are nested, so the\ncoarse-to-fine symbol split of codebook_torch (new symbols 2a, 2a+1 refine a) stays exact.  No emission\nnoise: a leaf\'s symbol is its cell, a symbol\'s value is its cell mean (design rule of Q4).\n"""\nimport copy\nimport numpy as np\nimport torch\nimport codebook_torch as cbt\n\n\nclass TSVQ:\n    def __init__(self, X, depth_max, iters=15):\n        X = np.asarray(X, float)\n        self.cent = {0: X.mean(0, keepdims=True)}\n        idx = np.zeros(len(X), dtype=np.int64)\n        for k in range(1, depth_max + 1):\n            new = np.zeros((2 ** k, X.shape[1]))\n            for a in range(2 ** (k - 1)):\n                pts = X[idx == a]\n                if len(pts) < 2:\n                    new[2 * a] = new[2 * a + 1] = self.cent[k - 1][a]\n                    continue\n                mu = pts.mean(0)\n                direc = np.linalg.svd(pts - mu, full_matrices=False)[2][0]\n                lab = (pts - mu) @ direc > 0\n                for _ in range(iters):\n                    c0 = pts[~lab].mean(0) if (~lab).any() else mu\n                    c1 = pts[lab].mean(0) if lab.any() else mu\n                    lab = ((pts - c1) ** 2).sum(1) < ((pts - c0) ** 2).sum(1)\n                new[2 * a], new[2 * a + 1] = c0, c1\n            self.cent[k] = new\n            c0 = new[2 * idx]; c1 = new[2 * idx + 1]\n            idx = 2 * idx + (((X - c1) ** 2).sum(1) < ((X - c0) ** 2).sum(1))\n        self.X, self.depth_max = X, depth_max\n        self.cent_t = {k: torch.tensor(v, dtype=torch.float32, device=cbt.DEV) for k, v in self.cent.items()}\n\n    def assign(self, Xt, depth):\n        """Xt torch (N, d) -> cell index at `depth` (descend the tree)."""\n        idx = torch.zeros(Xt.shape[0], dtype=torch.long, device=Xt.device)\n        for k in range(1, depth + 1):\n            c = self.cent_t[k]\n            d0 = ((Xt - c[2 * idx]) ** 2).sum(1); d1 = ((Xt - c[2 * idx + 1]) ** 2).sum(1)\n            idx = 2 * idx + (d1 < d0).long()\n        return idx\n\n    def means(self, depth):\n        idx = self.assign(torch.tensor(self.X, dtype=torch.float32, device=cbt.DEV), depth).cpu().numpy()\n        c = self.cent[depth].copy()\n        for a in range(2 ** depth):\n            if (idx == a).any():\n                c[a] = self.X[idx == a].mean(0)\n        return c\n\n\nclass VQCodebook(cbt.QCodebook):\n    def __init__(self, M, c, quant, depth):\n        super().__init__(M, c, np.zeros(1))\n        self.quant, self.depth = quant, depth\n\n\ndef vq_fit_coarse_to_fine(X, v_final, rng, v0=4, restarts=4, iters=300, tol=1e-8):\n    X = np.asarray(X, float)\n    Xf = X.reshape(-1, X.shape[-1])\n    dmax = int(round(np.log2(v_final))); d0 = int(round(np.log2(v0)))\n    quant = TSVQ(Xf, dmax)\n    best = None\n    for _ in range(restarts):\n        M = rng.dirichlet(np.ones(v0), size=(3, v0)).transpose(0, 2, 1)\n        cb, ll = cbt.q_run_em(VQCodebook(M, quant.means(d0), quant, d0), X, iters, tol)\n        if best is None or ll > best[1]:\n            best = (cb, ll)\n    cb, ll = best\n    out = {v0: (cb, ll)}\n    for depth in range(d0 + 1, dmax + 1):\n        v = cb.v\n        M = cb.M.cpu().numpy()\n        w = 0.5 + 0.05 * rng.uniform(-1, 1, size=(3, v, v))\n        order = np.repeat(np.arange(v), 2)\n        M2 = np.zeros((3, 2 * v, 2 * v))\n        for i in range(3):\n            child = np.stack([M[i][order[a2]] * (w[i][order[a2]] if a2 % 2 == 0 else 1 - w[i][order[a2]])\n                              for a2 in range(2 * v)])\n            M2[i] = child[:, order]\n        cb, ll = cbt.q_run_em(VQCodebook(M2, quant.means(depth), quant, depth), X, iters, tol)\n        out[2 * v] = (cb, ll)\n    return out\n')
_install('codebook_smooth', '"""Structured (smooth) kernel on the adaptive codebook (srhm.tex section 8.10).\n\n  log M_i[a\' | a] = -||c_a\' - phi_i(c_a; theta)||^2 / (2 psi^2) + log w_a\' - log Z_i(a)\n\nphi_i(z) = b_i + L_i z + B_i tanh(A_i z + a_i)  (small network in LEAF coordinates, tied across heights).\nLeaves: hard tree-structured quantization (codebook_vq.TSVQ); c = cell means.  Beliefs over the v symbols\nare exact (sum-product, codebook_torch).  Learning = generalized EM: exact E-step (pooled grid-local pair\nstatistics), M-step = gradient steps on sum_{i,a,a\'} pair_i[a,a\'] log M_i[a\'|a] over (theta, psi, w).\nRefining the codebook (larger v) reuses theta unchanged.\n"""\nimport copy\nimport math\nimport numpy as np\nimport torch\nimport codebook_torch as cbt\nimport codebook_vq as vq\n\nS = 3\nDEV = cbt.DEV\n\n\nclass SmoothKernel(torch.nn.Module):\n    def __init__(self, d, hidden=16, seed=0):\n        super().__init__()\n        g = torch.Generator().manual_seed(seed)\n        r = lambda *sh, s=1.0: (torch.randn(*sh, generator=g) * s)\n        self.b = torch.nn.Parameter(r(S, d, s=0.1))\n        self.Lm = torch.nn.Parameter(r(S, d, d, s=0.7 / math.sqrt(d)))\n        self.A = torch.nn.Parameter(r(S, hidden, d, s=1.0 / math.sqrt(d)))\n        self.a = torch.nn.Parameter(r(S, hidden, s=0.1))\n        self.B = torch.nn.Parameter(r(S, d, hidden, s=0.3 / math.sqrt(hidden)))\n        self.log_psi = torch.nn.Parameter(torch.tensor(math.log(0.6)))\n        self.log_w = None\n\n    def phi(self, z):\n        """z (n, d) -> (S, n, d)"""\n        h = torch.tanh(torch.einsum("shd,nd->snh", self.A, z) + self.a[:, None, :])\n        return self.b[:, None, :] + torch.einsum("sed,nd->sne", self.Lm, z) + torch.einsum("seh,snh->sne", self.B, h)\n\n    def M(self, c):\n        """c (v, d) codebook -> M (S, v, v) with M[i, a\', a] = P(child a\' | parent a)."""\n        v = c.shape[0]\n        if self.log_w is None or self.log_w.shape[0] != v:\n            self.log_w = torch.nn.Parameter(torch.zeros(v, device=c.device))\n        mu = self.phi(c)                                                     # (S, v_parent, d)\n        d2 = ((c[None, :, None, :] - mu[:, None, :, :]) ** 2).sum(-1)        # (S, a\', a)\n        logits = -d2 / (2 * torch.exp(2 * self.log_psi)) + self.log_w[None, :, None]\n        return torch.softmax(logits, dim=1)\n\n\ndef fit(X, v_list, seed=0, em_iters=60, m_steps=25, lr=0.03, restarts=3, tol=1e-6):\n    """Generalized EM, coarse-to-fine over v_list (theta reused).  Returns {v: (kernel, codebook, ll)}."""\n    X = np.asarray(X, float)\n    d = X.shape[-1] if X.ndim == 3 else 1\n    Xf = X.reshape(-1, d)\n    quant = vq.TSVQ(Xf, int(round(math.log2(max(v_list)))))\n    out, best_state = {}, None\n    for vi, v in enumerate(v_list):\n        depth = int(round(math.log2(v)))\n        c = torch.tensor(quant.means(depth), dtype=torch.float32, device=DEV)\n        starts = range(restarts) if vi == 0 else [None]\n        best = None\n        for rs in starts:\n            ker = SmoothKernel(d, seed=seed * 100 + rs).to(DEV) if rs is not None else best_state\n            ker.M(c)                                                         # (re)create cell weights\n            opt = torch.optim.Adam(ker.parameters(), lr=lr)\n            prev = -math.inf\n            for it in range(em_iters):\n                with torch.no_grad():\n                    cb = vq.VQCodebook(ker.M(c), c, quant, depth)\n                    pair, _, _, ll = cbt.q_estep(cb, X)\n                pair = pair.float()\n                for _ in range(m_steps):                                      # M-step: local statistics only\n                    Mx = ker.M(c)\n                    obj = -(pair.transpose(1, 2) * torch.log(Mx + 1e-30)).sum() / pair.sum()\n                    opt.zero_grad(); obj.backward(); opt.step()\n                if ll - prev < tol * abs(ll):\n                    break\n                prev = ll\n            with torch.no_grad():\n                ll = cbt.q_estep(vq.VQCodebook(ker.M(c), c, quant, depth), X)[3]\n            if best is None or ll > best[0]:\n                best = (ll, ker)\n        best_state = best[1]\n        with torch.no_grad():\n            out[v] = (copy.deepcopy(best_state), vq.VQCodebook(best_state.M(c), c, quant, depth), best[0])\n        best_state.log_w = None                                               # re-sized at next v\n    return out\n\n\ndef phi_error(ker, true_phi, Z, psi):\n    """Mean over positions of RMS ||phi_hat_i(z) - phi_i(z)|| over latent samples Z, in units of psi."""\n    with torch.no_grad():\n        ph = ker.phi(torch.tensor(Z, dtype=torch.float32, device=DEV)).cpu().numpy()   # (S, n, d)\n    tr = true_phi(Z)                                                                   # (n, S, d)\n    return float(np.mean([np.sqrt(((ph[i] - tr[:, i]) ** 2).sum(-1).mean()) for i in range(S)]) / psi)\n')
"""Structured (smooth) kernel on the adaptive codebook, d = 2 (srhm.tex section 8.10).
Same processes, oracles and test trees as exp_v2.py.  Data: (1,7) N1=729, (1,8) 2187, (3,8) 6561,
(9,8) 19683; coarse-to-fine v = 8 -> 256 with theta reused; 2 kernels x 2 seeds; zero labels.
Reports root R^2 (vs oracle) and the error of the learned maps phi_i under the stationary law (S3).
"""
import os, sys, json, time
import numpy as np
import torch

import ngt_nd as nd, codebook_torch as cbt, codebook_vq as vq, codebook_smooth as sm

DATA = [(1, 7), (1, 8), (3, 8), (9, 8)]
VS = [8, 16, 32, 64, 128, 256]


def r2v(p, R):
    return float(1 - ((p - R) ** 2).sum() / ((R - R.mean(0)) ** 2).sum())


def main():
    print(json.dumps(dict(event="start", device=cbt.DEV)), flush=True)
    for kseed in (200, 201):
        ker = nd.random_kernel(2, np.random.default_rng(kseed))
        T, R = nd.sample_trees(ker, 300, 6, np.random.default_rng(7))
        Z = nd.sample_trees(ker, 3000, 0, np.random.default_rng(3))[0][:, 0]          # stationary latents
        r2o = r2v(nd.GridOracle(ker, n=101, lim=5.0).root_mean(T), R)
        print(json.dumps(dict(event="oracle", kernel=kseed, r2_oracle=round(r2o, 4))), flush=True)
        for (U, L) in DATA:
            for seed in range(2):
                X, _ = nd.sample_trees(ker, U, L, np.random.default_rng(1000 * kseed + seed))
                t = time.time()
                fits = sm.fit(X, VS, seed=seed, em_iters=40, restarts=2)
                for v, (k, cb, ll) in sorted(fits.items()):
                    print(json.dumps(dict(kernel=kseed, U=U, L=L, N1=U * 3 ** (L - 1), seed=seed, v=v,
                                          r2=round(r2v(cbt.q_root_value(cb, T), R), 4), r2_oracle=round(r2o, 4),
                                          phi_err=round(sm.phi_error(k, ker.phi, Z, ker.psi), 4),
                                          psi_hat=round(float(torch.exp(k.log_psi.detach())), 4),
                                          secs_total=round(time.time() - t, 1))), flush=True)
    print(json.dumps(dict(event="done")), flush=True)


if __name__ == "__main__":
    main()
